            if inp[j] != outp[j]:
                print(f"Position {j}: '{inp[j]}' -> '{outp[j]}'")
                break
        else:
            if len(inp) != len(outp):
                print(f"Length change: {len(inp)} -> {len(outp)}")
            else:
                print("Unknown difference")

